do $release$ declare payload jsonb:='{"batch":"nl-scale-20261102-046","project":"hlvujbrmfdlrfxdjwsmb","actions":[{"ref":"d0","relation":"catalog_work_descriptions","key":{"work_id":987145013,"language":"nl"},"before":null,"after":{"work_id":987145013,"language":"nl","bound_author_id":987300009,"text":"Tijdens een reis door Amerika besluit Jack Reacher het plaatsje te bezoeken waar zijn vader vandaan zou komen. Bij navraag blijkt niemand de familienaam te kennen. Zijn nieuwsgierigheid groeit naarmate het vertrouwde verhaal over zijn afkomst minder zeker wordt. In dezelfde omgeving strandt een jong Canadees stel bij een afgelegen motel. Terwijl Reacher naar antwoorden zoekt, ontwikkelen zich elders gebeurtenissen waarvan het gevaar nog niet meteen zichtbaar is. Het verleden en de huidige dreiging komen geleidelijk dichter bij elkaar.","source_type":"official_catalog","source_name":"Gecontroleerde boek- en catalogusbronnen","source_url":"https://openlibrary.org/works/OL19754749W","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p418130825","http://data.bibliotheken.nl/id/nbt/p421380144","http://data.bibliotheken.nl/id/nbt/p421379979"],"checked_at":"2026-11-03T09:19:36.616Z","reference":"work:2999","note":"PastTense2018 and VerledenTijd exactDutchPaperback9789024577194, ReacherNewHampshire/motel narrative. ExistingDutch edition reused; summaryonly, no newWorkoravailabilityclaim.","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-015.json","sources":["https://openlibrary.org/works/OL19754749W","https://data.bibliotheken.nl/id/nbt/p418130825","https://data.bibliotheken.nl/id/nbt/p421380144","https://data.bibliotheken.nl/id/nbt/p421379979"]},{"type":"no_verified_cover_asset_retained","status":"no_verified_asset_retained","editionKey":"/books/OL37784301M","isbn13":"9789024577194","checkedAt":"2026-11-03T09:19:36.616Z","note":"Source-bound bulk attempt yielded no ver